  window.cpSaveQuestionnaire = async function(projectId) {
    var overlay = document.getElementById('cp-q-overlay');
    var scope = overlay || document;
    var pd = getPD(projectId);
    var project = pd ? pd.project : null; if (!project) return;
    var questions = project.questionnaireQuestions || [];
    var answers = {};
    questions.forEach(function(q) {
      if (q.type === 'section') return;
      if (q.type === 'choice') {
        var g = scope.querySelector('[data-qgroup="' + q.id + '"]');
        var sel = g ? g.querySelector('input:checked') : null;
        answers[q.id] = sel ? sel.value : '';
      } else if (q.type === 'multi') {
        var g2 = scope.querySelector('[data-qgroup="' + q.id + '"]'); var vals = [];
        if (g2) g2.querySelectorAll('input:checked').forEach(function(c) { vals.push(c.value); });
        answers[q.id] = vals;
      } else if (q.type === 'rank') {
        var g3 = scope.querySelector('[data-qgroup="' + q.id + '"]'); var obj = {};
        if (g3) g3.querySelectorAll('input[data-opt]').forEach(function(n) { var v = (n.value || '').trim(); if (v) obj[n.getAttribute('data-opt')] = parseInt(v, 10) || v; });
        answers[q.id] = obj;
      } else {
        var e = scope.querySelector('[data-qid="' + q.id + '"]');
        answers[q.id] = e ? (e.value || '').trim() : '';
      }
    });
    var body = { questionnaireAnswers: answers, projectId: projectId };
    var res = await fetch(API_BASE + '/notes', { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
    if (res.ok) {
      if (pd) pd.project.questionnaireAnswers = answers;
      if (overlay) overlay.remove();
      toast('Réponses enregistrées ✓');
      renderShell();
    } else { toast('Erreur enregistrement'); }
  };

  window.cpTab = function(btn, panel) {
    var tabs = btn.closest('.cp-tabs');
    if (tabs) tabs.querySelectorAll('.cp-tab').forEach(function(t) { t.classList.remove('active'); });
    btn.classList.add('active');
    ['files','prac','meet','msg','liv'].forEach(function(id) {
      var el = document.getElementById('cp-panel-' + id);
      if (el) el.classList[id===panel?'remove':'add']('hidden');
    });
  };

  function attachForm() {
    var form = document.getElementById('cp-msg-form');
    if (!form) return;
    form.addEventListener('submit', function(e) {
      e.preventDefault();
      var content = form.content.value.trim();
      if (!content) return;
      var btn = form.querySelector('button[type=submit]');
      btn.disabled = true; btn.textContent = 'Envoi…';
      fetch(API_BASE + '/conversation', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ content: content }),
      })
        .then(function(r) { if (!r.ok) throw new Error(); return r.json(); })
        .then(function(d) {
          convData.push(d.message);
          var list = document.getElementById('cp-msgs-list');
          var empty = list && list.querySelector('.cp-empty');
          if (empty) empty.remove();
          var div = document.createElement('div');
          div.className = 'cp-msg cp-msg--client';
          div.innerHTML = '<div class="cp-msg__av cp-msg__av--client">' + clientInitial + '</div>' +
            '<div class="cp-msg__bubble"><div class="cp-msg__text">' + fmtMsg(d.message.content) + '</div>' +
            '<div class="cp-msg__date">Vous · maintenant</div></div>';
          if (list) { list.appendChild(div); div.scrollIntoView({ behavior:'smooth', block:'nearest' }); }
          form.content.value = '';
          toast('Message envoyé ✓');
        })
        .catch(function() { toast('Erreur, réessayez.'); })
        .finally(function() { btn.disabled = false; btn.textContent = 'Envoyer →'; });
    });
  }

  

  function cpRefreshBadge() {
    var unreadNow = totalUnread();
    document.querySelectorAll('[data-nav="messages"] .cp-nav__badge').forEach(function(b){ b.remove(); });
    if (unreadNow > 0) {
      var msgBtn = document.querySelector('[data-nav="messages"]');
      if (msgBtn) { var b = document.createElement('span'); b.className = 'cp-nav__badge'; b.textContent = String(unreadNow); msgBtn.appendChild(b); }
    }
  }
  var _pollBusy = false;
  function startPoll() {
    // Rafraîchissement doux : badge de messages non lus partout, et fil de
    // conversation ouvert mis à jour sans toucher au brouillon en cours.
    setInterval(function() {
      if (!API_BASE || !appData) return;
      if (_isAdminEdit) return; // pas de remplacement des données pendant l'édition
      if (typeof document !== 'undefined' && document.visibilityState === 'hidden') return;
      if (_pollBusy) return; _pollBusy = true;
      var headers = {};
      try { var sc = sessionStorage.getItem('_sc'); if (sc) headers['x-space-code'] = sc; } catch(e) {}
      fetch(API_BASE, { headers: headers })
        .then(function(r){ if (!r.ok) throw new Error(); return r.json(); })
        .then(function(data) {
          if (!data || data.wrongCode || data.locked || !data.projects) return;
          appData = data;
          cpRefreshBadge();
          // Messagerie ouverte : mise à jour en direct (messages + fichiers reçus).
          if (typeof window.stbInboxRefresh === 'function') { try { window.stbInboxRefresh(); } catch(e){} }
        })
        .catch(function(){})
        .then(function(){ _pollBusy = false; });
    }, 90000);
    wireReturnRefresh();
  }

  // Rafraîchissement quand la cliente REVIENT sur l'onglet (retour au dashboard),
  // et non à chaque navigation interne (trop gourmand). Recharge tout l'espace et
  // re-rend la vue courante, sans réinitialiser la navigation. Throttlé.
  var _lastReturnRefresh = 0, _returnWired = false;
  function refreshOnReturn() {
    if (!API_BASE || !appData || _isAdminEdit) return;
    // Ne pas re-render pendant l'édition d'une tâche ouverte (sinon on remonte en haut).
    if (typeof document !== 'undefined' && document.querySelector('.cp-task-overlay')) return;
    var now = Date.now();
    if (now - _lastReturnRefresh < 12000) return;
    _lastReturnRefresh = now;
    var headers = {};
    try { var sc = sessionStorage.getItem('_sc'); if (sc) headers['x-space-code'] = sc; } catch(e) {}
    fetch(API_BASE, { headers: headers })
      .then(function(r){ return r.ok ? r.json() : null; })
      .then(function(data){
        if (!data || data.wrongCode || data.locked) return;
        var norm = normalizeAppData(data);
        if (!norm) return;
        var h = data.home || {};
        norm.home = { intro:(typeof h.intro==='string'?h.intro:null), blocks:Array.isArray(h.blocks)?h.blocks:[], hidden:(h.hidden&&typeof h.hidden==='object')?h.hidden:{}, banner:(h.banner&&typeof h.banner==='object')?h.banner:{} };
        appData = norm;
        convData = Array.isArray(data.conversation) ? data.conversation : convData;
        cpHolidays = Array.isArray(data.studioHolidays) ? data.studioHolidays : cpHolidays;
        var ids = (appData.projects||[]).map(function(p){ return p.project.id; });
        if (ids.indexOf(currentId) === -1 && ids.length) currentId = ids[0];
        renderShell();
      })
      .catch(function(){});
  }
  function wireReturnRefresh() {
    if (_returnWired || typeof document === 'undefined') return;
    _returnWired = true;
    document.addEventListener('visibilitychange', function(){ if (document.visibilityState === 'visible') refreshOnReturn(); });
    if (typeof window !== 'undefined') window.addEventListener('focus', function(){ refreshOnReturn(); });
  }

  function buildClientFileExchange(pid, files) {
    var adminFiles = (files||[]).filter(function(f){ return f.source !== 'client'; });
    var clientFiles = (files||[]).filter(function(f){ return f.source === 'client'; });
    function fileRow(f) {
      var ico = f.type && f.type.startsWith('image/') ? '🖼' : f.type === 'application/pdf' ? '📄' : '📎';
      return '<div style="display:flex;align-items:center;gap:10px;padding:10px 14px;border:1px solid var(--border);border-radius:10px;background:var(--surface);margin-bottom:6px">' +
        '<span style="font-size:16px">' + ico + '</span>' +
        '<div style="flex:1;min-width:0"><div style="font-weight:500;font-size:13px;color:var(--navy);overflow:hidden;text-overflow:ellipsis;white-space:nowrap">' + esc(f.name) + '</div>' +
          '<div style="font-size:11px;color:var(--muted)">' + (f.uploadedAt ? new Date(f.uploadedAt).toLocaleDateString('fr-FR') : '') + (f.size ? ' · ' + fmtSize(f.size) : '') + '</div></div>' +
        '<a href="' + API_BASE + '/files/' + encodeURIComponent(f.key) + '/download" target="_blank" class="cp-btn cp-btn--outline" style="padding:5px 12px;font-size:12px">↓</a>' +
      '</div>';
    }
    return '<div class="cp-card">' +
      '<div class="cp-card__hd"><h2 class="cp-card__title">Documents partagés</h2></div>' +
      (adminFiles.length
        ? '<div style="margin-bottom:20px">' + adminFiles.map(fileRow).join('') + '</div>'
        : '<div style="color:var(--muted);font-size:13px;margin-bottom:20px">Aucun document partage pour le moment.</div>') +
      '<div style="border-top:1px solid var(--border);padding-top:16px">' +
        '<div style="font-weight:600;font-size:13px;color:var(--navy);margin-bottom:10px">Vos dépôts</div>' +
        (clientFiles.length ? '<div style="margin-bottom:12px">' + clientFiles.map(fileRow).join('') + '</div>' : '<div style="color:var(--muted);font-size:13px;margin-bottom:12px">Aucun fichier deposé.</div>') +
        '<label style="display:flex;align-items:center;justify-content:center;gap:8px;padding:14px;border:2px dashed var(--border);border-radius:10px;cursor:pointer;color:var(--muted);font-size:13px" for="cli-file-up-' + pid + '">' +
          cpIcon('upload',13) + ' Déposer un fichier' +
          '<input type="file" id="cli-file-up-' + pid + '" style="display:none" onchange="cliUploadClientFile(\'' + pid + '\',this)">' +
        '</label>' +
      '</div>' +
    '</div>';
  }

